// ─────────────────────────────────────────────────────────────────────────────
// Сцены на корейском
//
// ПОДЛИННЫЕ ТЕКСТЫ — из 위키문헌 (корейская Викитека). Хён Джингон (ум. 1943),
// Ким Юджон (ум. 1937) и Ким Донин (ум. 1951) в общественном достоянии.
//
// ЧЕСТНО ПРО УРОВЕНЬ. Корейская классика 1920–30-х — это TOPIK 5급, а не 3급,
// и занижать метку нельзя: там довоенная лексика, деревенская речь и обороты,
// которых в современном языке нет. Ставить «Счастливый день» рядом с текстом
// про кафе значило бы отправить ученика на стену.
//
// Поэтому у обоих рассказов заполнен `source.caveat`: предупреждение выводится
// ДО текста. Классику здесь читают ради того, как это написано, — а лексику на
// каждый день берут из современных сцен и разговорника.
// ─────────────────────────────────────────────────────────────────────────────

