    setup: 'Сеул, зима, моросит ледяной дождь. Рикша Ким Чхомджи десять дней не видел денег, а сегодня с самого утра ему везёт: два седока подряд. Дома лежит больная жена, которая уже месяц кашляет и которую ни разу не показывали врачу.',
    after: 'Везение будет продолжаться весь день — Ким заработает больше, чем за месяц, и купит жене тот самый соллонтхан, о котором она просила. Название рассказа означает ровно то, что написано, и одновременно прямо противоположное.',
    body: `새침하게 흐린 품이 눈이 올 듯하더니 눈은 아니 오고 얼다가 만 비가 추적추적 내리었다.

이날이야말로 동소문 안에서 인력거꾼 노릇을 하는 김 첨지에게는 오래간만에도 닥친 운수 좋은 날이었다. 문안에(거기도 문밖은 아니지만) 들어간답시는 앞집 마나님을 전찻길까지 모셔다 드린 것을 비롯으로 행여나 손님이 있을까 하고 정류장에서 어정어정하며 내리는 사람 하나하나에게 거의 비는 듯한 눈결을 보내고 있다가 마침내 교원인 듯한 양복장이를 동광학교(東光學校)까지 태워다 주기로 되었다.

첫번에 삼십 전, 둘째 번에 오십 전 - 아침 댓바람에 그리 흔치 않은 일이었다. 그야말로 재수가 옴붙어서 근 열흘 동안 돈 구경도 못한 김 첨지는 십 전짜리 백통화 서 푼, 또는 다섯 푼이 찰깍하고 손바닥에 떨어질 제 거의 눈물을 흘릴 만큼 기뻤었다. 더구나 이날 이때에 이 팔십 전이라는 돈이 그에게 얼마나 유용한지 몰랐다. 컬컬한 목에 모주 한 잔도 적실 수 있거니와 그보다도 앓는 아내에게 설렁탕 한 그릇도 사다줄 수 있음이다.

그의 아내가 기침으로 쿨럭거리기는 벌써 달포가 넘었다. 조밥도 굶기를 먹다시피 하는 형편이니 물론 약 한 첩 써 본 일이 없다.`,
    translation: `Небо хмурилось так, будто вот-вот пойдёт снег, но снег не пошёл, а зарядил зябкий дождь пополам с ледышками.

Именно этот день выдался для Ким Чхомджи, промышлявшего извозом на рикше в квартале Тонсомун, давно не выпадавшим счастливым днём. Началось с того, что он довёз до трамвайной линии соседскую хозяйку, собравшуюся в город (хотя и здесь, положим, не загородье), а потом топтался у остановки в надежде на седока, посылая почти умоляющий взгляд каждому сходящему, — и наконец подрядился отвезти человека в европейском костюме, похожего на учителя, до школы Тонгван (東光學校).

Первый раз — тридцать чон, второй — пятьдесят. Для раннего утра дело нечастое. Ким Чхомджи, которому так не везло, что он без малого десять дней не видел денег, чуть не плакал от радости, когда три, а то и пять медных монеток по десять чон со звоном падали ему в ладонь. Тем более он и сам не знал, до чего кстати пришлись сейчас эти восемьдесят чон. На них можно было и промочить пересохшее горло чаркой мутной браги, а главное — купить больной жене миску соллонтхана.

Жена его кашляла уже больше месяца. Жили так, что и просяная каша была не каждый день, — понятно, что за всё это время ей не купили ни одной порции лекарства.`,
