    order: 2, where: 'Наш текст на тему сериала', size: 'short', spoiler: 1,
    textOrigin: 'ours', origin: 'original',
    setup: 'Сериал охватывает шестьдесят лет, и половина его — про то, как родители с острова отпускают детей на материк. Ниже наше письмо матери. Написано оно почти целиком на стандартном корейском — так и писали, — но своих родителей она называет по-чеджуски, и в этом вся точка: диалект остаётся там, где остаётся дом.',
    after: 'Предпоследний абзац — единственный, где сказано прямо: «я пишу это письмо только чтобы спросить, ешь ли ты. Остальное — так, к слову». Всё, что выше, и есть это «остальное».',
    body: `서울 우리 딸 보아라.

돈은 잘 받았다. 안 보내도 된다고 몇 번을 말했는데 또 보냈더구나. 다음 달부터는 보내지 마라. 어멍은 아직 시장에 나간다. 다리는 괜찮다.

아방은 요새 기침을 한다. 병원에는 안 간다고 한다. 무사 안 가느냐고 물으면 바쁘다고 한다. 삼월에 밭일이 뭐가 그리 바쁘겠느냐. 네가 전화해서 한번 말해 봐라. 네 말은 듣는다.

집은 그대로다. 지붕은 작년에 고쳤고 감나무는 올해도 열렸다. 옆집 할망이 네 사진을 보고 이제 서울 사람 다 됐다고 하더라. 좋은 말인지 아닌지 나는 잘 모르겠다.

밥은 먹고 다니느냐. 이 편지는 그것만 물으려고 쓴다. 나머지는 다 그냥 하는 말이다.

몸조심해라. 급한 일 있으면 전화해라. 밤에도 괜찮다.

제주에서 어멍이`,
    translation: `Дочке моей в Сеул.

Деньги дошли. Сколько раз говорила — не присылай, а ты опять прислала. Со следующего месяца не присылай. Мать пока ходит на рынок. С ногой всё нормально.

Отец в последнее время кашляет. В больницу, говорит, не пойду. Спрашиваю, почему не идёшь, — отвечает, что занят. Какие в марте на поле такие уж дела. Позвони, скажи ему сама. Тебя он слушает.

Дом стоит как стоял. Крышу в прошлом году починили, хурма и в этом году уродилась. Соседская бабушка посмотрела твою фотографию и сказала, что ты теперь совсем сеульская. Хорошо это или нет — я так и не поняла.

Ты ешь-то нормально? Я это письмо только затем и пишу, чтобы спросить. Всё остальное — так, к слову.

Береги себя. Если что срочное — звони. И ночью можно.

С Чеджу, мать`,
