    textOrigin: 'ours', origin: 'original',
    setup: 'Сюжет начинается с того, что школа отказывается признать происходящее происшествием. Ниже наше заявление в комиссию по школьному насилию. Это канцелярский корейский в чистом виде: 귀중, 민원인, -하고자 합니다, -기 바랍니다. Такую бумагу приходится читать и писать в жизни куда чаще, чем кажется.',
