    textOrigin: 'ours', origin: 'original',
    setup: 'В сериале семья и компания — одно и то же место, и потому семейный праздник оформляют как корпоративное мероприятие. Ниже два текста об одном событии: официальное приглашение и чат тех же самых людей. Разрыв между ними и есть весь корейский регистровый диапазон, от 근계 до ㅇㅇ.',
