    order: 1, where: 'Наш текст на тему сериала', size: 'short', spoiler: 1,
    textOrigin: 'ours', origin: 'original',
    setup: 'Героиня попадает в 2008 год и оказывается в собственной школе. Ниже наш классный уголок того времени. Это самый простой текст на полке и первый, который стоит открыть на корейском: короткие предложения, настоящее время, ничего кроме школьного быта — расписание, дежурство, что принести завтра.',
    after: 'Обратите внимание на счётные слова: 1교시, 2교시 для уроков и 1번부터 8번까지 для учеников по номерам в журнале. По номеру в корейской школе называют так же обычно, как по имени.',
    body: `2학년 5반 알림장

■ 오늘 시간표
1교시 국어 / 2교시 수학 / 3교시 체육 / 4교시 영어
점심시간에 체육관에서 반 대항 농구 경기가 있습니다. 3반과 합니다. 응원 오세요.

■ 준비물
내일 미술 시간에 색연필을 가져오세요. 안 가져오면 옆 사람과 같이 써야 합니다.
체육복은 사물함에 두지 말고 집에 가져가서 빨아 오세요.

■ 청소
이번 주 청소 당번은 1번부터 8번까지입니다. 교실과 복도를 합니다.
칠판은 그날 마지막 수업을 한 사람이 지웁니다.

■ 알림
다음 주 월요일은 중간고사입니다. 시험 범위는 칠판 옆에 붙여 두었습니다.
축제 신청은 금요일까지입니다. 노래, 춤, 밴드 다 됩니다. 신청서는 교무실 앞에 있습니다.

■ 선생님 말씀
쉬는 시간에 복도에서 뛰지 마세요. 지난주에 두 명이 다쳤습니다.
휴대폰은 아침에 걷고 종례 때 돌려줍니다. 안 내면 일주일 동안 못 받습니다.`,
    translation: `Классный уголок, 2 класс «5»

■ Расписание на сегодня
1-й урок — корейский / 2-й — математика / 3-й — физкультура / 4-й — английский.
На большой перемене в спортзале матч по баскетболу между классами. Играем с 3-м классом. Приходите болеть.

■ Что принести
Завтра на рисовании нужны цветные карандаши. Кто не принесёт, будет делить с соседом.
Спортивную форму не оставляйте в шкафчике: заберите домой и постирайте.

■ Дежурство
На этой неделе дежурят с 1-го по 8-й номер. Убирают класс и коридор.
Доску стирает тот, у кого в этот день был последний урок.

■ Объявления
В следующий понедельник — контрольная за полугодие. Что войдёт, вывешено рядом с доской.
Заявки на школьный фестиваль — до пятницы. Можно песню, танец, группу. Бланки лежат у учительской.

■ От классного руководителя
На переменах в коридоре не бегать. На прошлой неделе двое получили травмы.
Телефоны собираем утром и отдаём на последней перекличке. Кто не сдал — не получит неделю.`,
