    order: 1, where: 'Наш текст на тему манги', size: 'short', spoiler: 1,
    textOrigin: 'ours', origin: 'original',
    setup: 'Правила тетради в манге написаны слогом инструкции — и по-корейски этот слог свой, узнаваемый. Ниже наш свод. Три вещи отсюда встретятся в любом договоре и правилах пользования: -하는 경우 («в случае, если»), -에 한한다 («только при условии»), -지 않는다 в конце пункта — форма письменного устава, а не разговора.',
    after: 'Пятый пункт — «незнание правил не является основанием» — по-корейски звучит как в настоящем законе: 이유가 되지 않는다. Именно на таких формулировках и держится ощущение, что тетрадь — не волшебство, а бюрократия.',
    body: `사용 규칙 (발췌)

一. 이 공책에 이름을 적은 경우, 그 효력은 적은 사람의 의도와 관계없이 발생한다.

二. 이름은 정확해야 한다. 동명이인이 둘 이상 있는 경우에는 효력이 발생하지 않는다.

三. 기재는 본인이 직접 쓴 경우에 한한다. 다른 사람에게 대신 쓰게 한 기재는 무효로 한다.

四. 기재 후에 취소를 신청할 수 있다. 다만, 신청이 반드시 받아들여지는 것은 아니다.

五. 이 규칙을 몰랐던 경우에도 규칙은 그대로 적용된다. 모르는 것은 이유가 되지 않는다.

六. 이 공책은 다른 사람에게 넘길 수 있다. 넘긴 사람은 넘겼다는 사실 자체를 잊는다. 다만, 이미 적은 이름의 기록은 남는다. 이에 대한 예외 조항은 없다.`,
    translation: `Правила пользования (выдержка)

1. В случае внесения имени в настоящую тетрадь действие наступает независимо от намерения внёсшего.

2. Имя должно быть точным. При наличии двух и более полных тёзок действие не наступает.

3. Запись действительна только при условии, что сделана лично. Запись, сделанная по поручению другим лицом, считается недействительной.

4. После внесения можно подать заявление об отмене. При этом заявление не обязательно будет принято.

5. Правила применяются и в том случае, если лицо о них не знало. Незнание не является основанием.

6. Тетрадь можно передать другому. Передавший забывает сам факт передачи. При этом запись уже внесённых имён сохраняется. Исключений на этот счёт не предусмотрено.`,
