    setup: 'Вторая половина манги — совещания, где версию проверяют вслух. Ниже наше такое совещание. Это ровно тот корейский, на котором ведут рабочий разбор: 가정하다 («допустим»), 전제 («посылка»), 모순되다 («противоречить»), 근거 («основание»).',
    after: 'Последняя реплика — рабочая формула на любой случай: 반박할 수 없다고 해서 증명된 것은 아닙니다. «Не опровергнуто» и «доказано» — разные вещи, и путают их не только в детективах.',
    body: `— 현재로서는 가능성이 세 가지입니다.

첫째, 범인이 공개된 보도만 보고 있는 경우입니다. 그렇다면 위치는 좁힐 수 없습니다. 전국 어디에 있어도 이상하지 않습니다.

둘째, 내부 자료를 보고 있는 경우입니다. 그렇게 가정하면 대상이 좁아집니다. 자료에 접근할 수 있는 사람은 열두 명입니다.

셋째는 둘 다입니다.

— 셋째부터 검토합시다. 근거는요?

첫째와 둘째는 각각 설명되지 않는 부분이 남습니다. 보도에 나오지 않은 내용을 알고 있습니다. 한편으로는, 내부 자료만으로는 설명이 안 되는 속도로 움직입니다.

— 두 전제 모두와 모순되는 사실이 있다는 말이군요.

그렇습니다. 지금까지 모순되지 않는 설명은 셋째뿐입니다.

— 알겠습니다. 다만 이건 기억해 두십시오. 반박할 수 없다고 해서 증명된 것은 아닙니다.`,
    translation: `— На сегодня возможностей три.

Первая: преступник смотрит только открытые сообщения прессы. Тогда сузить его местоположение мы не можем — он может быть где угодно в стране.

Вторая: он видит внутренние материалы. Если исходить из этого, круг сужается: доступ к материалам имеют двенадцать человек.

Третья — и то, и другое.

— Начнём разбор с третьей. Основание?

Первая и вторая оставляют по необъяснённому остатку. Он знает то, чего в сообщениях прессы не было. С другой стороны, действует быстрее, чем это объяснимо одними внутренними материалами.

— То есть есть факты, противоречащие обеим посылкам.

Именно. Не противоречит пока только третья.

— Понял. Но запомните вот что: то, что нельзя опровергнуть, ещё не значит доказанное.`,
