    setup: 'Всё, что происходит в фильме, начинается с обычной покупки билета на утренний KTX. Ниже наш текст — разговор в кассе Сеульского вокзала. Здесь ровно те слова, без которых в Корее не уехать: 매진, 입석, 창가, 환불, 승강장.',
    body: `— 부산 가는 표 있어요?
— 몇 시 걸로 드릴까요?
— 제일 빠른 거요.
— 열 시 사십 분 KTX가 있는데 좌석은 매진이고 입석만 남았습니다.
— 입석이면 서서 가는 거예요?
— 네. 두 시간 반 정도 서서 가셔야 해요.
— 다음 건요?
— 열한 시 이십 분에 좌석 있습니다. 창가 쪽으로 드릴까요?
— 네, 창가로 주세요. 어른 한 명이요.
— 오만 구천 원입니다. 카드 되시죠?
— 네. 아, 혹시 환불 되나요?
— 출발 전이면 됩니다. 출발한 뒤에는 수수료가 붙어요.
— 알겠습니다.
— 11호차 5A입니다. 승강장은 4번이고요. 좋은 여행 되세요.`,
    translation: `— Есть билеты до Пусана?
— На какое время вам?
— На самый ближайший.
— Есть KTX в десять сорок, но сидячие распроданы, остались только стоячие.
— Стоячий — это значит ехать стоя?
— Да. Придётся простоять примерно два с половиной часа.
— А следующий?
— В одиннадцать двадцать есть сидячие. Дать у окна?
— Да, у окна. Один взрослый.
— Пятьдесят девять тысяч вон. Картой можно?
— Да. А, скажите, вернуть билет можно?
— До отправления — можно. После отправления удерживается комиссия.
— Понятно.
— Вагон 11, место 5A. Платформа четвёртая. Счастливого пути.`,
