    order: 2, where: 'Наш текст на тему сериала', size: 'short', spoiler: 1,
    textOrigin: 'ours', origin: 'original',
    setup: 'Половина сериала — про то, как человек с Севера разбирается в южном быту, и это самая полезная его часть: те же вопросы задаёт любой приехавший. Ниже наш текст — квитанция за квартиру, оплата с телефона и посылка под дверью. Заодно тут вся лексика, с которой сталкиваешься в первую неделю в корейской квартире.',
    body: `— 이 종이가 뭡니까?
— 관리비 고지서예요. 아파트에 사시면 매달 나와요.
— 전기세하고 다릅니까?
— 전기, 수도, 청소, 경비… 다 합쳐서 나와요. 여기 합계만 보시면 돼요.
— 이건 어디서 냅니까?
— 은행에서도 되고 폰으로도 돼요. 제가 한번 해 드릴게요.
— 폰으로 돈이 나갑니까?
— 네. 앱에서 눌러서 이체하는 거예요.
— …무섭습니다.
— 처음엔 다 그래요. 저희 어머니도 아직 못 하세요.
— 하나 더 물어봐도 됩니까?
— 얼마든지요.
— 문 앞에 자꾸 물건이 놓여 있습니다. 누가 두고 갑니까?
— 아, 그건 택배예요. 시키신 거 아니에요?
— 시켰습니다. 그런데 사람이 부르지도 않고 갑니다.
— 요즘은 그냥 두고 가요. 문 앞에 놓고 사진 찍어서 보내 줘요.
— …편합니다. 편한데 이상합니다.`,
    translation: `— Что это за бумага?
— Квитанция за содержание жилья. Если живёшь в многоквартирном доме, приходит каждый месяц.
— Это не то же самое, что за электричество?
— Электричество, вода, уборка, охрана… всё вместе одной суммой. Достаточно смотреть на итог вот здесь.
— А где это оплачивают?
— Можно в банке, можно с телефона. Давайте я вам один раз покажу.
— С телефона деньги уходят?
— Да. Нажимаете в приложении и переводите.
— …Страшно.
— Сначала всем страшно. Моя мама до сих пор не умеет.
— Можно ещё один вопрос?
— Сколько угодно.
— У меня под дверью всё время появляются вещи. Кто их оставляет?
— А, так это доставка. Вы разве не заказывали?
— Заказывал. Но человек уходит, даже не позвонив.
— Сейчас так и оставляют. Кладут под дверь, фотографируют и присылают фото.
— …Удобно. Удобно, но странно.`,
