    textOrigin: 'ours', origin: 'original',
    setup: 'Второй регистр сагыка — не придворный, а уличный: 하오체, на котором говорят между собой простые люди, и казённый язык указа, вывешенного на столбе. Ниже наш текст обоих видов. Заметьте, что в сагыке грамотных мало, и объявление почти всегда кто-то читает вслух остальным.',
    body: `[방(榜)]

이 고을 백성들은 들으라.

하나. 오늘부터 해가 지면 성문을 닫는다. 밤에 문밖으로 나가는 자는 잡아 가둔다.
둘. 앓는 사람이 있는 집은 문에 표를 걸고 관아에 알려라. 숨기는 자는 그 집안을 함께 벌한다.
셋. 시신은 묻지 말고 태우라. 이는 나라의 명이다.

（저잣거리）

— 이보시오, 저기 뭐라고 쓰여 있소?
— 글을 모르오?
— 모르오.
— 해가 지면 나가지 말라 하오. 아픈 사람이 있으면 관아에 알리라 하고.
— 알리면 어찌 되오?
— …그건 쓰여 있지 않소.`,
    translation: `[Указ]

Люди сего уезда, слушайте.

Первое. С сего дня по заходе солнца городские ворота затворяются. Всякий, кто выйдет за ворота ночью, будет схвачен и посажен под замок.
Второе. Дом, где есть больной, обязан вывесить на дверях знак и известить управу. Кто утаит — будет наказан вместе со всем домом.
Третье. Тела не хоронить, а сжигать. Такова воля государства.

(Торговый ряд)

— Послушайте, что там написано?
— Грамоты не знаете?
— Не знаю.
— Велят по заходе солнца не выходить. А коли есть больной — известить управу.
— А что будет, если известить?
— …А вот этого там не написано.`,
