    setup: 'Фильм начинается с частного урока английского на дому — самой обычной для Кореи подработки. Ниже наше объявление о поиске репетитора с доски объявлений. Сюжета в нём нет, есть быт: сколько платят, сколько раз в неделю, что нужно принести.',
