    order: 0, where: 'Наш текст на тему сериала', size: 'flash', spoiler: 1,
    textOrigin: 'ours', origin: 'original',
    setup: 'Сериал назван по детской дворовой игре, и все его игры — настоящие, из корейского двора семидесятых. Ниже наше описание правил такой игры с площадки — без всякого отношения к сюжету: как играют дети, и всё. Правила — идеальный текст для 2급: сплошные запреты, разрешения и условия.',
    after: 'Весь текст — это три формы подряд: ~(으)면 «если», ~(으)면 안 돼요 «нельзя» и ~아/어도 돼요 «можно». В справочнике они стоят рядом и разбираются как тройка; выучив её, вы читаете любые правила и любое объявление.',
    body: `놀이터 안내 — «무궁화 꽃이 피었습니다»

몇 명이 해요?
세 명부터 할 수 있어요.
많으면 더 재미있어요.

어떻게 해요?
술래는 벽을 보고 서요.
술래가 «무궁화 꽃이 피었습니다»라고 말해요.
그동안 다른 사람은 앞으로 가요.

술래가 말을 끝내고 뒤를 봐요.
그때 움직이면 안 돼요.
움직이면 술래한테 잡혀요.

잡힌 사람은 술래 옆에 서요.
손을 잡고 기다려요.

누가 술래한테 닿으면 다 같이 도망가도 돼요.
술래가 «그만»이라고 말하면 멈춰야 해요.

주의
뛰다가 넘어질 수 있어요.
운동화를 신으세요.
어두우면 놀이터에서 놀지 마세요.`,
    translation: `Правила на площадке — «Мугунхва распустилась»

Сколько человек?
Играть можно от трёх.
Чем больше, тем веселее.

Как играть?
Водящий встаёт лицом к стене.
Водящий произносит: «Мугунхва распустилась».
Пока он говорит, остальные идут вперёд.

Договорив, водящий оборачивается.
В этот момент двигаться нельзя.
Кто пошевелился — попался.

Пойманный встаёт рядом с водящим.
Держит его за руку и ждёт.

Если кто-то дотронется до водящего, все могут убегать.
Когда водящий крикнет «стоп», надо замереть.

Осторожно
На бегу можно упасть.
Наденьте кроссовки.
В темноте на площадке не играйте.`,
