    setup: 'Регистр этой книги — простые слова и прямые вопросы, на которые взрослому трудно ответить. Ниже наш текст в том же ключе: ребёнок и сосед разговаривают у горшка на подоконнике. Грамматика здесь начальная, а лексика — про уход за растением: 물을 주다, 자라다, 시들다.',
    body: `— 아저씨, 이거 뭐예요?
— 화분이야. 안에 씨를 심었어.
— 아무것도 없는데요.
— 아직 안 나왔으니까.
— 언제 나와요?
— 몰라. 열흘일 수도 있고 한 달일 수도 있어.

— 매일 물을 줘요?
— 매일은 아니야. 흙을 만져 보고 마르면 줘.
— 많이 주면 빨리 자라요?
— 아니. 많이 주면 죽어.
— 이상해요.
— 이상하지. 그런데 사람도 그래.

（보름 뒤）

— 아저씨! 나왔어요!
— 어디.
— 여기요. 아주 작아요.
— 그래. 작지.
— 이제 제 거예요?
— 네 것은 아니야.
— 그럼 뭐예요?
— 네가 물을 준 거지. 그거면 충분해.`,
    translation: `— Дядя, а это что?
— Горшок. Я туда семечко посадил.
— Тут же ничего нет.
— Потому что ещё не взошло.
— А когда взойдёт?
— Не знаю. Может, дней через десять, а может, через месяц.

— Каждый день поливать?
— Не каждый. Потрогай землю: сухая — полей.
— А если много лить, вырастет быстрее?
— Нет. Если много — погибнет.
— Странно.
— Странно. А с людьми так же.

(Через полмесяца)

— Дядя! Взошло!
— Где?
— Вот тут. Совсем маленькое.
— Да. Маленькое.
— Теперь оно моё?
— Твоим оно не стало.
— А какое тогда?
— Такое, которое ты поливал. Этого достаточно.`,
